import{_ as a,o as i,a as t,b as n}from"./app.DKoEZOcr.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"语言扩展层","link":"/guide/programming_guide/language_extension/language_extension"},{"text":"SIMD语言扩展层C API","link":"/guide/programming_guide/language_extension/simd_language_extension_c_api"}]},"headers":[],"relativePath":"guide/programming_guide/language_extension/simd_language_extension_c_api.md","filePath":"guide/programming_guide/language_extension/simd_language_extension_c_api.md","lastUpdated":1786949923000}'),_={name:"guide/programming_guide/language_extension/simd_language_extension_c_api.md"};function l(s,e,o,r,g,d){return i(),t("div",null,[...e[0]||(e[0]=[n(`<div><article class="markdown-body"><h1>SIMD语言扩展层C API<span id="ZH-CN_TOPIC_0000002477823928"></span></h1><p>C API开放芯片完备编程能力，支持以数组形式分配内存，一般基于指针编程。提供与业界一致的C语言编程体验。</p><p>包含asc_simd.h文件来调用C API相应接口。如无特殊说明，包含该头文件即可满足接口调用需求。若<a href="../../../api/SIMD-API/c_api/c_api.html">API文档</a>中有特殊说明，则应遵循API的具体说明。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;c_api/asc_simd.h&quot;
</code></pre></div><p>对于C API，主要分为以下几类：</p><ul><li>矢量计算，实现调用Vector计算单元执行计算的功能。</li><li>数据搬运，计算API基于Local Memory数据进行计算，所以数据需要先从Global Memory搬运至Local Memory，再使用计算API完成计算，最后从Local Memory搬出至Global Memory。执行搬运过程的接口称之为数据搬运API。</li><li>同步控制，完成任务间的通信和同步，比如asc_sync_notify/asc_sync_wait接口。不同的API指令间有可能存在依赖关系，从<a href="../programming_model/ai_core_simd_programming/abstract_hardware_architecture.html">抽象硬件架构</a>可知，不同的指令异步并行执行，为了保证不同指令队列间的指令按照正确的逻辑关系执行，需要向不同的组件发送同步指令。同步控制API内部即完成这个发送同步指令的过程。</li><li>系统变量，访问、获取系统内置变量，辅助计算API。</li></ul><p>对于计算类API可以分为以下几类：</p><ul><li>前n个数据计算：该类型API在计算时采用“紧密排布”的数据读取方式，即从起始位置开始，按顺序连续获取所需数据。例如，若需处理N个数据，则从源操作数的第0个位置开始，依次取至第N-1个位置。</li><li>高维切分计算：该类型API按照设定的规则“跳过部分数据”。适合处理需要间隔采样的场景，灵活度高，但需要额外配置相关参数。</li><li>同步计算：该类型API内部自动插入同步操作，易用性更强。</li></ul></article></div>`,1)])])}const m=a(_,[["render",l]]);export{p as __pageData,m as default};
